/* In-memory only: maps a placement key -> current line index. Persists across
   renderLeft() re-renders (which happen on every score tap) so a line a host
   refreshed to mid-round doesn't snap back to the first line. Intentionally NOT
   saved to storage — banter resets fresh each session. */
let banterState={};
function banterLine(cat,key){
  const arr=BANTER[cat]||[];if(!arr.length)return'';
  let i=banterState[key];
  if(i==null||i<0||i>=arr.length){i=Math.floor(Math.random()*arr.length);banterState[key]=i;}
  return arr[i];
}
function renderBanter(cat,key,opts){
  opts=opts||{};
  const sm=opts.sm?' banter-sm':'';
  const showLabel=opts.label!==false;
  const lbl=BANTER_CAT_LABEL[cat]||'';
  const line=banterLine(cat,key);
  return `<div class="banter${sm}">`+
    `<div class="banter-main">`+
      (showLabel?`<span class="banter-cat">🎤 ${esc(lbl)}</span>`:'')+
      `<div class="banter-text" data-bkey="${key}">${esc(line)}</div>`+
    `</div>`+
    `<button class="banter-refresh" type="button" onclick="cycleBanter('${key}','${cat}')" title="New line" aria-label="Refresh banter line">🔄</button>`+
  `</div>`;
}
/* Pick a different random line, update ONLY that line's text node (no full
   re-render) so the refresh button never moves and scroll never jumps. */
function cycleBanter(key,cat){
  const arr=BANTER[cat]||[];if(arr.length<2){return;}
  let cur=banterState[key]??-1,next=cur;
  while(next===cur){next=Math.floor(Math.random()*arr.length);}
  banterState[key]=next;
  const el=document.querySelector('.banter-text[data-bkey="'+(window.CSS&&CSS.escape?CSS.escape(key):key)+'"]');
  if(el)el.textContent=arr[next];
}
const FONT_SIZES=[12,13,14,15,16,17,18,19,20,22,24,26,28,30],DEFAULT_SI=3;
const DENSITIES=['normal','compact','relaxed'],DENSITY_LABELS={normal:'Normal',compact:'Compact',relaxed:'Relaxed'};
const STRIPE_LEVELS=[0,1,2],STRIPE_LABELS={0:'Subtle',1:'Medium',2:'High'};

