function loadPrefs(){
  try{const r=TRStore.getItem(PREFS_KEY);if(r){const p=JSON.parse(r);if(!['hc-dark','hc-light'].includes(p.theme))p.theme=(['light','bw','hc-light'].includes(p.theme))?'hc-light':'hc-dark';if(p.sizeIndex==null)p.sizeIndex=DEFAULT_SI;if(!p.density)p.density='normal';if(p.settingsOpen==null)p.settingsOpen=false;if(p.stripeLevel==null)p.stripeLevel=0;if(!p.dateFmt)p.dateFmt='mdy';if(p.cbMode==null)p.cbMode=p.colorblind?1:0;if(!p.craftDrawSeconds)p.craftDrawSeconds=6;if(p.showAdjustments==null)p.showAdjustments=false;return p;}}catch(e){}
  return{theme:'hc-dark',sizeIndex:DEFAULT_SI,density:'normal',settingsOpen:false,stripeLevel:0,dateFmt:'mdy',cbMode:0,craftDrawSeconds:6,showAdjustments:false};
}
function savePrefs(p){TRStore.setItem(PREFS_KEY,JSON.stringify(p));}
function applyPrefs(){
  const p=loadPrefs();
  document.documentElement.setAttribute('data-theme',p.theme);
  const dn=p.density||'normal';
  if(dn==='normal')document.documentElement.removeAttribute('data-density');
  else document.documentElement.setAttribute('data-density',dn);
  const tb=document.getElementById('themeToggle');if(tb)tb.textContent=(p.theme==='hc-light')?'\u2600\uFE0F Light':'\uD83C\uDF11 Dark';
  const cbm=p.cbMode||0;
  if(cbm)document.documentElement.setAttribute('data-cb',String(cbm));else document.documentElement.removeAttribute('data-cb');
  setCvSelectDisplay(String(cbm));
  const si=Math.max(0,Math.min(FONT_SIZES.length-1,p.sizeIndex??DEFAULT_SI));
  document.documentElement.style.fontSize=FONT_SIZES[si]+'px';
  const sr=document.getElementById('sizeResetBtn');if(sr)sr.textContent=(si===DEFAULT_SI)?'A':FONT_SIZES[si]+'px';
  const dt=document.getElementById('densityToggle');if(dt)dt.textContent=DENSITY_LABELS[dn]||'Normal';
  const panel=document.getElementById('settingsPanel');if(panel)panel.classList.toggle('settings-visible',!!p.settingsOpen);
  const stb=document.getElementById('settingsToggleBtn');if(stb)stb.classList.toggle('active',!!p.settingsOpen);
  const sl=p.stripeLevel??0;
  if(sl===0)document.documentElement.removeAttribute('data-stripe');
  else document.documentElement.setAttribute('data-stripe',String(sl));
  const slt=document.getElementById('stripeToggle');if(slt)slt.textContent=STRIPE_LABELS[sl]||'Subtle';
  const dft=document.getElementById('dateFmtToggle');if(dft)dft.textContent=(p.dateFmt==='dmon')?'DD-Mon-YYYY':'MM-DD-YYYY';
  const adt=document.getElementById('adjToggle');if(adt){adt.classList.toggle('active',!!p.showAdjustments);adt.textContent=p.showAdjustments?'Shown':'Hidden';}
  const vl=document.getElementById('versionLabel');if(vl)vl.textContent='Scorekeeper '+APP_VERSION;
}
function setTheme(t){if(!['hc-dark','hc-light'].includes(t))t='hc-dark';const p=loadPrefs();p.theme=t;savePrefs(p);applyPrefs();}
function toggleTheme(){const p=loadPrefs();setTheme(p.theme==='hc-dark'?'hc-light':'hc-dark');}
function toggleAdjSetting(){const p=loadPrefs();p.showAdjustments=!p.showAdjustments;savePrefs(p);applyPrefs();renderLeft();}
function setCbMode(v){const p=loadPrefs();p.cbMode=parseInt(v,10)||0;savePrefs(p);applyPrefs();}

function closeCvMenu(){
  const w=document.getElementById('cbSelect');if(!w)return;
  w.classList.remove('open');
  w.querySelector('.cv-select-btn').setAttribute('aria-expanded','false');
}
function toggleCvMenu(e){
  e.stopPropagation();
  const w=document.getElementById('cbSelect');if(!w)return;
  const willOpen=!w.classList.contains('open');
  document.querySelectorAll('.cv-select.open').forEach(o=>{if(o!==w)o.classList.remove('open');});
  w.classList.toggle('open',willOpen);
  w.querySelector('.cv-select-btn').setAttribute('aria-expanded',String(willOpen));
  const menu=w.querySelector('.cv-select-menu');
  menu.removeAttribute('data-align');
  if(willOpen){
    // Clamp to the viewport: only flip to right-aligned if the default left-aligned
    // position would run off the right edge — this is the actual overflow bug.
    const r=menu.getBoundingClientRect();
    if(r.right>window.innerWidth-8)menu.setAttribute('data-align','right');
  }
}
function selectCvOption(li,v){
  setCvSelectDisplay(v);
  closeCvMenu();
  setCbMode(v);
}
function setCvSelectDisplay(v){
  const w=document.getElementById('cbSelect');if(!w)return;
  const li=w.querySelector('li[data-value="'+v+'"]');
  w.querySelectorAll('li').forEach(o=>o.setAttribute('aria-selected','false'));
  if(li){li.setAttribute('aria-selected','true');const lbl=w.querySelector('.cv-select-label');if(lbl)lbl.textContent=li.dataset.short||li.textContent.trim();}
}
document.addEventListener('click',e=>{if(!e.target.closest('.cv-select'))closeCvMenu();});
