function toggleStripe(){const p=loadPrefs();const ci=STRIPE_LEVELS.indexOf(p.stripeLevel??0);p.stripeLevel=STRIPE_LEVELS[(ci+1)%STRIPE_LEVELS.length];savePrefs(p);applyPrefs();}
function adjustFontSize(d){const p=loadPrefs();if(d===0)p.sizeIndex=DEFAULT_SI;else p.sizeIndex=Math.max(0,Math.min(FONT_SIZES.length-1,(p.sizeIndex??DEFAULT_SI)+d));savePrefs(p);applyPrefs();}
function toggleSettings(){const p=loadPrefs();p.settingsOpen=!p.settingsOpen;savePrefs(p);applyPrefs();}

