// Round 2's halftime wager and Round 4's final wager already get a fun emoji + their own
// accent color (\u23F8 magenta, \uD83C\uDFAF orange) via renderSpecialWager \u2014 this gives Round 1 and Round 3's
// bonus question the same treatment, reusing the color each round is already tagged with
// elsewhere (rl-1 cyan, rl-3 gold) so it's consistent rather than a brand-new color choice.
const BONUS_Q_STYLE={0:{emoji:'\uD83C\uDF81',cls:'bq-r1'},2:{emoji:'\uD83C\uDF40',cls:'bq-r3'}};
function renderBQ(ri){
  const n=gameState.teams.length;
  let subDone=0;for(let ti=0;ti<n;ti++){if(gameState.rounds[ri].bonus[ti]!=null)subDone++;}
  const beer=isBonusBeerRound(ri);
  let badge='';
  if(n){
    if(beer)badge='<span class="q-badge q-badge-lg q-complete">\uD83C\uDF7A Beer Round!</span>';
    else if(subDone===n)badge='<span class="q-badge q-badge-lg q-complete">\u2713 Done</span>';
    else badge=`<span class="q-badge q-badge-lg q-remaining">${n-subDone} left</span>`;
  }
  const isCollapsedBQ=collapsedBonusQuestions.has('b'+ri);
  const blockCls='question-block'+(beer?' beer-round':'')+(isCollapsedBQ?' bq-collapsed':'');
  const bqStyle=BONUS_Q_STYLE[ri]||{emoji:'',cls:''};
  let h=`<div class="${blockCls}" id="bqblock-${ri}"><div class="q-header"><div class="q-header-left" role="button" tabindex="0" onclick="toggleBonusQ(${ri})"><span class="q-chevron">\u25BC</span><div class="question-title bonus-title"><div class="bonus-title-top"><span class="${bqStyle.cls}">${bqStyle.emoji} Q5 \u2014 Bonus</span>${badge}</div><span class="bonus-subtitle">0\u20134 CORRECT \u00D7 5 PTS</span></div></div></div>${beer?'<div class="beer-stripe"><span class="beer-stripe-icon">\uD83C\uDF7A</span><span class="beer-stripe-text">Beer Round! Everyone got all 4!</span></div>':''}<div class="q-body">`;
  gameState.teams.forEach((t,ti)=>{
    const v=gameState.rounds[ri].bonus[ti];
    const submitted=v!=null;
    const c=submitted?v:0;
    let ptsHtml;
    if(!submitted)ptsHtml=`<span class="bonus-pts pts-zero">\u2014</span>`;
    else if(c>0)ptsHtml=`<span class="bonus-pts pts-pos">+${c*5}</span>`;
    else ptsHtml=`<span class="bonus-pts submitted-zero">\u2713 0</span>`;
    const choices=[0,1,2,3,4].map(k=>{
      const isSel=submitted&&c===k;
      let cls='bonus-choice-btn',cbadge='';
      if(isSel&&k===0){cls+=' incorrect';cbadge='<span class="wager-badge bg-incorrect">\u2715</span>';}
      else if(isSel&&k>0){cls+=' correct';cbadge='<span class="wager-badge bg-correct">\u2705</span>';}
      return `<button class="${cls}" onclick="setB(${ri},${ti},${k})" title="${k} correct \u2014 +${k*5} pts \u2014 tap again to unselect">${k}${cbadge}</button>`;
    }).join('');
    h+=`<div class="bonus-row${submitted?' is-submitted':''}"><span class="ta-name ta-name-clickable" role="button" tabindex="0" title="${esc(t.name||'Team '+(ti+1))} \u2014 tap to audit score" onclick="openAudit(${ti})">${esc(t.name||'T'+(ti+1))}</span>
      <div class="bonus-right"><div class="bonus-choice">${choices}</div>
      ${ptsHtml}</div></div>`;
  });
  return h+`</div></div>`;
}

// Halftime and final wagers are identical except for range, labels and setters.
function renderSpecialWager(type){
  const isFinal=type==='final';
  const data=isFinal?gameState.finalWager:gameState.halftime;
  const max=isFinal?20:10;
  const sectionCls=isFinal?'special-section final-wager':'special-section';
  const titleMain=isFinal?'\uD83C\uDFAF Q5 \u2014 Final Wager':'\u23F8 Q5 \u2014 Bonus Wager';
  const titleSub=isFinal?'1\u201320 pts, win or lose':'1\u201310 pts, win or lose';
  const wSet=isFinal?'setFW':'setHW', cSet=isFinal?'setFC':'setHC', iSet=isFinal?'setFWInput':'setHWInput';
  const beer=isSpecialBeerRound(type);
  const swN=gameState.teams.length;let swDone=0;for(let ti=0;ti<swN;ti++){const d=data[ti];if(d&&d.wager!=null&&d.wager!==''&&d.correct!=null)swDone++;}
  let swBadge='';if(swN){if(beer)swBadge='<span class="q-badge q-complete">\uD83C\uDF7A Beer Round!</span>';else if(swDone===swN)swBadge='<span class="q-badge q-complete">\u2713 Done</span>';else swBadge=`<span class="q-badge q-remaining">${swN-swDone} left</span>`;}
  const swCollapsed=collapsedSpecialWagers.has(type);
  let h=`<div class="${sectionCls}${beer?' beer-round':''}${swCollapsed?' sw-collapsed':''}" id="swblock-${type}"><div class="sw-header" role="button" tabindex="0" onclick="toggleSpecialWager('${type}')"><span class="q-chevron">\u25BC</span><h3>${titleMain}<span class="sw-range">${titleSub}</span></h3>${swBadge}</div>`;
  if(beer)h+=`<div class="beer-stripe"><span class="beer-stripe-icon">\uD83C\uDF7A</span><span class="beer-stripe-text">Beer Round! Everyone got it right!</span></div>`;
  h+=`<div class="sw-body">`;
  gameState.teams.forEach((t,ti)=>{
    const d=data[ti]||{};
    const w=d.wager!=null&&d.wager!==''?+d.wager:null;
    let pts=`<span class="ta-pts pts-zero">\u2014</span>`;
    if(w!=null&&d.correct!=null){const p=d.correct?w:-w;pts=`<span class="ta-pts ${p>0?'pts-pos':p<0?'pts-neg':'pts-nil'}">${p>0?'+':''}${p}</span>`;}
    const valHtml=`<input type="number" class="sw-input" inputmode="numeric" min="1" max="${max}" value="${w!=null?w:''}" placeholder="\u2014" onchange="${iSet}(${ti},this.value)" onfocus="this.select()">`;
    const canDec=w!=null&&w>1, canInc=w==null||w<max;
    h+=`<div class="special-wager-row">
      <span class="ta-name ta-name-clickable" role="button" tabindex="0" title="${esc(t.name||'Team '+(ti+1))} \u2014 tap to audit score" onclick="openAudit(${ti})">${esc(t.name||'T'+(ti+1))}</span>
      <div class="stepper">
        <button onclick="${wSet}(${ti},${w!=null?Math.max(1,w-1):1})" ${!canDec?'disabled style="opacity:.3;cursor:default"':''}>\u2212</button>
        ${valHtml}
        <button onclick="${wSet}(${ti},${w!=null?Math.min(max,w+1):1})" ${!canInc?'disabled style="opacity:.3;cursor:default"':''}>+</button>
      </div>
      <div class="ta-result">
        <button class="result-btn ${d.correct===true?'correct-sel':''}" onclick="${cSet}(${ti},true)" aria-label="Mark correct">\u2713${d.correct===true?'<span class="wager-badge bg-correct">\u2705</span>':''}</button>
        <button class="result-btn ${d.correct===false?'incorrect-sel':''}" onclick="${cSet}(${ti},false)" aria-label="Mark incorrect">\u2717${d.correct===false?'<span class="wager-badge bg-incorrect">\u2715</span>':''}</button>
      </div>
      ${pts}
    </div>`;
  });
  return h+`</div></div>`;
}
