// CRAFT PRIZE RANDOMIZER — drumroll + name-flash + spoken winner script. Only ever one winner.
const DRUM_START_DUR=2.03,DRUM_END_DUR=3.9;
let drumStartAudio=null,drumEndAudio=null;
function getDrumAudio(){
  if(!drumStartAudio){
    drumStartAudio=new Audio('data:audio/mp3;base64,'+DRUM_START_B64);
    drumEndAudio=new Audio('data:audio/mp3;base64,'+DRUM_END_B64);
  }
  return{start:drumStartAudio,end:drumEndAudio};
}
// The loop clip is played via the Web Audio API instead of <audio loop> — HTMLMediaElement's
// built-in loop attribute re-buffers on every repeat, which produces an audible gap/click each
// time it restarts. AudioBufferSourceNode decodes the whole clip once and loops it sample-accurately.
let drumAudioCtx=null,drumLoopBuffer=null,drumLoopSource=null;
function getDrumAudioCtx(){
  if(!drumAudioCtx)drumAudioCtx=new (window.AudioContext||window.webkitAudioContext)();
  return drumAudioCtx;
}
function getDrumLoopBuffer(){
  if(drumLoopBuffer)return Promise.resolve(drumLoopBuffer);
  const ctx=getDrumAudioCtx();
  const bin=atob(DRUM_LOOP_B64);
  const bytes=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
  return ctx.decodeAudioData(bytes.buffer).then(buf=>{drumLoopBuffer=buf;return buf;});
}
function startDrumLoop(){
  const ctx=getDrumAudioCtx();
  if(ctx.state==='suspended')ctx.resume();
  getDrumLoopBuffer().then(buf=>{
    stopDrumLoop();
    const src=ctx.createBufferSource();
    src.buffer=buf;src.loop=true;
    src.connect(ctx.destination);
    src.start(0);
    drumLoopSource=src;
  });
}
function stopDrumLoop(){
  if(!drumLoopSource)return;
  try{drumLoopSource.stop();}catch(e){}
  try{drumLoopSource.disconnect();}catch(e){}
  drumLoopSource=null;
}
function stopAllDrumAudio(){
  stopDrumLoop();
  if(!drumStartAudio)return;
  [drumStartAudio,drumEndAudio].forEach(a=>{try{a.pause();a.currentTime=0;}catch(e){}});
}
function clearCraftDrawTimers(){
  craftDrawTimeouts.forEach(id=>clearTimeout(id));craftDrawTimeouts=[];
  if(craftDrawState&&craftDrawState.flashTimer)clearInterval(craftDrawState.flashTimer);
}
function craftPrizeScript(ti){
  const t=gameState.teams[ti];
  const name=t?.name||'Team '+(ti+1);
  const brewery=gameState.meta.craftPartner||'our craft partner';
  const town=(gameState.meta.craftPartnerTown||'').trim();
  return `Congratulations to ${name}! You've won a craft beer gift card to ${brewery}${town?' in '+town:''}. Cheers!`;
}
function setExcludeTopN(v){
  const n=Math.max(1,Math.min(20,parseInt(v,10)||2));
  gameState.meta.excludeTopN=n;autosave();renderLeft();
}
function setCraftDrawSeconds(v){
  const n=Math.max(3,Math.min(30,parseInt(v,10)||6));
  const p=loadPrefs();p.craftDrawSeconds=n;savePrefs(p);renderLeft();
}
function updateCraftScript(val){
  if(gameState.craftPrizeWinner){gameState.craftPrizeWinner.script=val;autosave();}
}
// The top N places (N = exclude-top setting) don't compete for the one craft-beer prize.
function craftEligiblePool(){
  const n=gameState.meta.excludeTopN||2;
  const topN=new Set(ranked().slice(0,n).map(r=>r.index));
  return gameState.teams.map((_,i)=>i).filter(i=>!topN.has(i));
}
function startCraftPrizeDraw(){
  if(craftDrawState&&craftDrawState.active)return;
  if(gameState.craftPrizeWinner){alert('The craft prize winner has already been chosen!');return;}
  const pool=craftEligiblePool();
  if(!pool.length){alert('No eligible teams left for the drawing (top-ranked teams are excluded)!');return;}
  const {start,end}=getDrumAudio();
  const prefs=loadPrefs();
  const totalMs=Math.max(3,Math.min(30,prefs.craftDrawSeconds||6))*1000;
  craftDrawState={active:true,pool,displayName:gameState.teams[pool[0]].name||('Team '+(pool[0]+1))};
  clearCraftDrawTimers();
  stopAllDrumAudio();
  try{start.currentTime=0;start.play();}catch(e){}
  craftDrawState.flashTimer=setInterval(()=>{
    const ti=pool[Math.floor(Math.random()*pool.length)];
    const name=gameState.teams[ti]?.name||('Team '+(ti+1));
    if(craftDrawState)craftDrawState.displayName=name;
    // Update the flash text node directly — a full renderLeft() 9x/sec would rebuild the
    // entire left column for no reason, since only this one line of text is changing.
    const el=document.getElementById('cpFlashName');
    if(el)el.textContent=name;else renderLeft();
  },110);
  // Loop plays for the entire countdown, starting once the intro clip's natural runtime ends.
  const loopStartAt=Math.min(DRUM_START_DUR*1000,totalMs);
  craftDrawTimeouts.push(setTimeout(()=>{
    stopAllDrumAudio();
    startDrumLoop();
  },loopStartAt));
  // End stinger only fires once the timer has fully elapsed — never overlaps the loop.
  craftDrawTimeouts.push(setTimeout(()=>{
    clearCraftDrawTimers();
    stopAllDrumAudio();
    try{end.currentTime=0;end.play();}catch(e){}
    const winnerTi=pool[Math.floor(Math.random()*pool.length)];
    gameState.teams.forEach(t=>{t.craftPrize=false;});
    gameState.teams[winnerTi].craftPrize=true;
    gameState.craftPrizeWinner={ti:winnerTi,script:craftPrizeScript(winnerTi)};
    craftDrawState=null;
    scoreSortMode='asc';
    autosave();
    renderAll();
  },totalMs));
  renderLeft();
}
function clearCraftPrizeWinner(){
  if(!gameState.craftPrizeWinner)return;
  if(!confirm('Clear the craft prize winner? You can run the drumroll again after.'))return;
  clearCraftDrawTimers();
  stopAllDrumAudio();
  gameState.teams.forEach(t=>{t.craftPrize=false;});
  gameState.craftPrizeWinner=null;
  autosave();
  renderAll();
}
function renderCraftPrizeBlock(){
  const n=gameState.teams.length;
  if(!n)return'<p class="fr-note">Add teams to run the craft prize drawing.</p>';
  const excludeN=gameState.meta.excludeTopN||2;
  const poolLeft=craftEligiblePool().length;
  const prefs=loadPrefs();
  const secs=prefs.craftDrawSeconds||6;
  const drawing=!!(craftDrawState&&craftDrawState.active);
  const winner=gameState.craftPrizeWinner;
  let h=`<div class="cp-config">
      <div class="cp-field"><span class="cp-field-label">Exclude Top</span><div class="stepper">
        <button onclick="setExcludeTopN(${Math.max(1,excludeN-1)})" ${(drawing||excludeN<=1)?'disabled style="opacity:.3;cursor:default"':''} aria-label="Decrease excluded places">−</button>
        <input type="number" class="sw-input" inputmode="numeric" min="1" max="20" value="${excludeN}" ${drawing?'disabled':''} onchange="setExcludeTopN(this.value)">
        <button onclick="setExcludeTopN(${Math.min(20,excludeN+1)})" ${(drawing||excludeN>=20)?'disabled style="opacity:.3;cursor:default"':''} aria-label="Increase excluded places">+</button>
      </div></div>
      <div class="cp-field"><span class="cp-field-label">Drumroll (sec)</span><div class="stepper">
        <button onclick="setCraftDrawSeconds(${Math.max(3,secs-1)})" ${(drawing||secs<=3)?'disabled style="opacity:.3;cursor:default"':''} aria-label="Decrease drumroll seconds">−</button>
        <input type="number" class="sw-input" inputmode="numeric" min="3" max="30" value="${secs}" ${drawing?'disabled':''} onchange="setCraftDrawSeconds(this.value)">
        <button onclick="setCraftDrawSeconds(${Math.min(30,secs+1)})" ${(drawing||secs>=30)?'disabled style="opacity:.3;cursor:default"':''} aria-label="Increase drumroll seconds">+</button>
      </div></div>
    </div>
    <div class="cp-note">Top ${excludeN} place${excludeN>1?'s':''} ${excludeN>1?'are':'is'} excluded — there's only one craft beer prize</div>`;
  if(drawing){
    h+=`<div class="cp-intro">🎙️ Now choosing our Craft Beer Prize winner…</div><div class="cp-flash" id="cpFlashName">${esc(craftDrawState.displayName||'')}</div>`;
  }else{
    h+=`<button class="btn btn-accent cp-draw-btn" onclick="startCraftPrizeDraw()" ${(winner||poolLeft<=0)?'disabled':''}>🥁 Choose Craft Prize Winner</button>`;
  }
  if(winner&&!drawing){
    const wname=gameState.teams[winner.ti]?.name||'Team '+(winner.ti+1);
    h+=`<div class="cp-winner">🏆 <strong>${esc(wname)}</strong> won! <button class="btn btn-danger cp-clear-btn" onclick="clearCraftPrizeWinner()" title="Clear the winner and run the drawing again">Clear</button></div>
      <label class="cp-script-label">Winner Announcement Script</label>
      <textarea class="cp-script" onchange="updateCraftScript(this.value)">${esc(winner.script)}</textarea>`;
  }
  return h;
}

function addTeam(){if(gameState.teams.length>=MAX_TEAMS)return;gameState.teams.push(freshTeam(''));autosave();renderAll();}
// Shift all integer keys above the removed index down by one (returns a new map).
function reindexAfterRemoval(map,ti){const out={};for(const k in map){const i=parseInt(k,10);if(i<ti)out[i]=map[k];else if(i>ti)out[i-1]=map[k];}return out;}
function removeTeam(ti){
  const name=gameState.teams[ti]?.name||'Team '+(ti+1);
  if(!confirm('Remove "'+name+'"?'))return;
  gameState.teams.splice(ti,1);
  const newAdj=new Set();adjOpenTeams.forEach(i=>{if(i<ti)newAdj.add(i);else if(i>ti)newAdj.add(i-1);});adjOpenTeams=newAdj;
  for(let ri=0;ri<4;ri++){
    for(let qi=0;qi<4;qi++)gameState.rounds[ri].questions[qi]=reindexAfterRemoval(gameState.rounds[ri].questions[qi],ti);
    gameState.rounds[ri].bonus=reindexAfterRemoval(gameState.rounds[ri].bonus,ti);
  }
  gameState.halftime=reindexAfterRemoval(gameState.halftime,ti);
  gameState.finalWager=reindexAfterRemoval(gameState.finalWager,ti);
  autosave();renderAll();
}
function toggleAdj(ti){if(adjOpenTeams.has(ti))adjOpenTeams.delete(ti);else adjOpenTeams.add(ti);renderLeft();}
function adjPts(ti,d){if(!gameState.teams[ti])return;gameState.teams[ti].adjustment=(gameState.teams[ti].adjustment||0)+d;autosave();renderAll();}
function cycleW(ri,qi,ti,w){
  if(!canScore())return;
  const q=gameState.rounds[ri].questions[qi];
  const a=q[ti]||{};
  if(a.wager===w){
    // same wager re-clicked: correct -> incorrect -> fully cleared (remove the slot entirely)
    if(a.correct===true)a.correct=false;
    else delete q[ti];
  }else{
    // blocked duplicate returns without ever creating an empty slot
    if(usedW(ti,ri).find(u=>u.wager===w&&u.qi!==qi))return;
    a.wager=w;a.correct=true;q[ti]=a;
  }
  const wasBeer=beerRoundToasted.has(ri+'-'+qi);
  lastAction={ri,qi,ti};gameState.gameStarted=true;autosave();
  // Check beer round BEFORE re-render so we can set beer flash context
  const nowBeer=isBeerRound(ri,qi);
  if(nowBeer&&!wasBeer){lastAction.beerRound=true;}
  renderAll();
  checkBeerRound(ri,qi);
  setTimeout(()=>{lastAction=null;},900);
}
function markAll(ri,qi,correct){
  if(!canScore())return;
  const wasBeer=beerRoundToasted.has(ri+'-'+qi);
  gameState.teams.forEach((_,ti)=>{const a=gameState.rounds[ri].questions[qi][ti];if(a&&a.wager!==undefined)a.correct=correct;});
  lastAction=null;gameState.gameStarted=true;autosave();renderAll();
  if(correct&&!wasBeer)checkBeerRound(ri,qi);
}
// Guard: before the very first scoring action, every team must have a guess entered.
// After the game has started once, this check is bypassed.
function canScore(){
  if(gameState.gameStarted)return true;
  const missing=gameState.teams.reduce((acc,t,i)=>{
    if(t.scoreGuess===''||t.scoreGuess==null)acc.push(t.name||('Team '+(i+1)));
    return acc;
  },[]);
  if(missing.length===0)return true;
  alert('Please enter a score guess for all teams before scoring begins.\n\nMissing guess:\u00a0'+missing.join(', '));
  // Scroll the Teams section into view so the user can fix it
  const sec=document.getElementById('sec-teams');
  if(sec){if(sec.classList.contains('collapsed'))sec.classList.remove('collapsed');sec.scrollIntoView({behavior:'smooth',block:'start'});}
  return false;
}
function setB(ri,ti,v){if(!canScore())return;const cur=gameState.rounds[ri].bonus[ti];if(cur===v){delete gameState.rounds[ri].bonus[ti];}else{gameState.rounds[ri].bonus[ti]=v;}gameState.gameStarted=true;autosave();renderAll();}
function clearB(ri,ti){delete gameState.rounds[ri].bonus[ti];autosave();renderAll();}
function setHW(ti,v){if(!canScore())return;if(!gameState.halftime[ti])gameState.halftime[ti]={};gameState.halftime[ti].wager=Math.max(1,Math.min(10,+v||1));gameState.gameStarted=true;autosave();renderAll();}
function setHC(ti,v){if(!canScore())return;const d=gameState.halftime[ti];if(!d||d.wager==null||d.wager==='')return;/* need a wager first */const c=d.correct;if(c===v)delete d.correct;else d.correct=v;gameState.gameStarted=true;autosave();renderAll();}
function setFW(ti,v){if(!canScore())return;if(!gameState.finalWager[ti])gameState.finalWager[ti]={};gameState.finalWager[ti].wager=Math.max(1,Math.min(20,+v||1));gameState.gameStarted=true;autosave();renderAll();}
function setFC(ti,v){if(!canScore())return;const d=gameState.finalWager[ti];if(!d||d.wager==null||d.wager==='')return;/* need a wager first */const c=d.correct;if(c===v)delete d.correct;else d.correct=v;gameState.gameStarted=true;autosave();renderAll();}

// Manual typed entry for the special wagers (works alongside the +/- steppers)
function setHWInput(ti,raw){
  if(!canScore())return;
  if(!gameState.halftime[ti])gameState.halftime[ti]={};
  const s=(''+raw).trim();
  if(s===''||parseInt(s,10)===0){delete gameState.halftime[ti].wager;}
  else{let v=parseInt(s,10);if(!isNaN(v)){gameState.halftime[ti].wager=Math.max(1,Math.min(10,v));}}
  gameState.gameStarted=true;autosave();renderAll();
}
function setFWInput(ti,raw){
  if(!canScore())return;
  if(!gameState.finalWager[ti])gameState.finalWager[ti]={};
  const s=(''+raw).trim();
  if(s===''||parseInt(s,10)===0){delete gameState.finalWager[ti].wager;}
  else{let v=parseInt(s,10);if(!isNaN(v)){gameState.finalWager[ti].wager=Math.max(1,Math.min(20,v));}}
  gameState.gameStarted=true;autosave();renderAll();
}

// ===== SCORE AUDIT =====
function openAudit(ti){
  const el=document.getElementById('auditModal');if(!el)return;
  el.innerHTML=buildAudit(ti);
  document.getElementById('auditOverlay').classList.add('show');
}
function closeAudit(){document.getElementById('auditOverlay').classList.remove('show');}

function auditQLine(ri,qi,ti){
  const a=gameState.rounds[ri].questions[qi][ti]||{};
  const hasW=a.wager!==undefined,hasR=a.correct!==undefined;
  let res,pts,pcls;
  if(!hasW){res='<span class="aud-res aud-none">no wager placed</span>';pts='\u2014';pcls='none';}
  else if(!hasR){res='<span class="aud-res aud-pending">wager '+a.wager+' \u2014 not marked</span>';pts='\u2014';pcls='none';}
  else if(a.correct){res='<span class="aud-res aud-correct">\u2713 correct</span>';pts='+'+a.wager;pcls='pos';}
  else{res='<span class="aud-res aud-wrong">\u2717 incorrect</span>';pts='0';pcls='zero';}
  const wtxt=hasW?('wager '+a.wager):'\u2014';
  return `<div class="aud-line"><span class="aud-q">Q${qi+1}</span><span class="aud-wager">${wtxt}</span>${res}<span class="aud-p ${pcls}">${pts}</span></div>`;
}

function buildAudit(ti){
  const t=gameState.teams[ti];if(!t)return'';
  const name=esc(t.name||'Team '+(ti+1));
  const rk=ranked();const rm={};rk.forEach((r,i)=>{rm[r.index]=i+1;});
  const rank=rm[ti];
  let h=`<div class="audit-head"><h2>${name}<span class="aud-sub">Score audit \u2014 rank #${rank} of ${gameState.teams.length} \u00B7 ${esc(gameState.meta.location||'')}${gameState.meta.quizId?(' \u00B7 Quiz '+esc(gameState.meta.quizId)):''}</span></h2><button class="audit-close" onclick="closeAudit()">\u2715 Close</button></div>`;
  h+=`<div class="audit-body">`;

  let run=0;
  function roundBlock(ri,label,colorCls){
    let b=`<div class="aud-round"><div class="aud-round-h"><span class="round-label ${colorCls}">${label}</span><span style="color:var(--text-muted);font-weight:400;font-size:.68rem;letter-spacing:0;text-transform:none">wagers ${ROUND_WAGERS[ri].join(', ')}</span></div>`;
    for(let qi=0;qi<4;qi++)b+=auditQLine(ri,qi,ti);
    if(BONUS_ROUNDS.has(ri)){
      const v=gameState.rounds[ri].bonus[ti];
      let res,pts,pcls;
      if(v==null){res='<span class="aud-res aud-none">not marked</span>';pts='\u2014';pcls='none';}
      else if(v>0){res='<span class="aud-res aud-correct">'+v+' of 4 correct</span>';pts='+'+(v*5);pcls='pos';}
      else{res='<span class="aud-res aud-wrong">0 of 4 correct (submitted)</span>';pts='0';pcls='zero';}
      b+=`<div class="aud-line"><span class="aud-q">B</span><span class="aud-wager">bonus \u00D75</span>${res}<span class="aud-p ${pcls}">${pts}</span></div>`;
    }
    const sub=roundSub(ti,ri);run+=sub;
    b+=`<div class="aud-subline"><span class="lbl">${label} subtotal</span><span><span class="sub">${sub}</span> &nbsp;\u00B7&nbsp; total so far <span class="run">${run}</span></span></div>`;
    return b+`</div>`;
  }
  function wagerBlock(data,label,colorCls,maxTxt){
    const w=data&&data.wager!=null&&data.wager!==''?+data.wager:null;
    let res,pts,pcls;
    if(w==null){res='<span class="aud-res aud-none">no wager placed</span>';pts='\u2014';pcls='none';}
    else if(data.correct==null){res='<span class="aud-res aud-pending">wager '+w+' \u2014 not marked</span>';pts='\u2014';pcls='none';}
    else if(data.correct){res='<span class="aud-res aud-correct">\u2713 correct</span>';pts='+'+w;pcls='pos';}
    else{res='<span class="aud-res aud-wrong">\u2717 incorrect</span>';pts='\u2212'+w;pcls='neg';}
    const p=(w!=null&&data.correct!=null)?(data.correct?w:-w):0;run+=p;
    let b=`<div class="aud-round"><div class="aud-round-h"><span class="round-label ${colorCls}">${label}</span><span style="color:var(--text-muted);font-weight:400;font-size:.68rem;letter-spacing:0;text-transform:none">${maxTxt}</span></div>`;
    b+=`<div class="aud-line"><span class="aud-q">\u2605</span><span class="aud-wager">${w!=null?('wager '+w):'\u2014'}</span>${res}<span class="aud-p ${pcls}">${pts}</span></div>`;
    b+=`<div class="aud-subline"><span class="lbl">after ${label}</span><span>total so far <span class="run">${run}</span></span></div>`;
    return b+`</div>`;
  }

  // Extras \u2014 bonus item and NJCB card are checked in before the game starts, so show
  // them first; the running "total so far" in every later block includes them from the start.
  const item=t.bonusItem?5:0,nj=t.njcb?3:0,adj=t.adjustment||0;
  if(item||nj||adj){
    h+=`<div class="aud-round"><div class="aud-round-h"><span class="round-label rl-3">Extras</span></div>`;
    if(item)h+=`<div class="aud-line"><span class="aud-q">+5</span><span class="aud-res aud-correct">Bonus item brought</span><span class="aud-p pos">+5</span></div>`;
    if(nj)h+=`<div class="aud-line"><span class="aud-q">+3</span><span class="aud-res aud-correct">NJCB Member Card shown</span><span class="aud-p pos">+3</span></div>`;
    if(adj)h+=`<div class="aud-line"><span class="aud-q">${adj>0?'+':''}${adj}</span><span class="aud-res">Manual adjustment</span><span class="aud-p ${adj>0?'pos':'neg'}">${adj>0?'+':''}${adj}</span></div>`;
    run+=item+nj+adj;
    h+=`</div>`;
  }

  h+=roundBlock(0,'Round 1','rl-1');
  h+=roundBlock(1,'Round 2','rl-2');
  h+=wagerBlock(gameState.halftime[ti],'Halftime Bonus','rl-2','win or lose, 1\u201310');
  h+=roundBlock(2,'Round 3','rl-3');
  h+=roundBlock(3,'Round 4','rl-4');
  h+=wagerBlock(gameState.finalWager[ti],'Final Wager','rl-4','win or lose, 1\u201320');

  const gt=grandTotal(ti);
  h+=`<div class="aud-total"><span>Grand Total</span><span class="val">${gt}</span></div>`;
  if(run!==gt)h+=`<div class="aud-note">Note: running figure (${run}) and grand total (${gt}) differ \u2014 if you see this, take a screenshot.</div>`;
  else h+=`<div class="aud-note">Tip: each round shows that question's wager, whether it was marked correct or incorrect, and the team's running score. To fix a wrong wager, close this and tap the wager button in the round itself.</div>`;
  h+=`</div>`;
  return h;
}
function toggleSection(id){if(collapsedSections.has(id))collapsedSections.delete(id);else collapsedSections.add(id);const el=document.getElementById(id);if(el)el.classList.toggle('collapsed');}

function saveToFile(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(gameState,null,2)],{type:'application/json'}));a.download=exportFn('json').replace('.json','-save.json');a.click();}
function triggerLoadFile(){if(confirm('Replace current session?'))document.getElementById('fileLoadInput').click();}
function loadFromFile(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=function(ev){let data;try{data=JSON.parse(ev.target.result);}catch(err){alert('Bad JSON \u2014 this file isn\u2019t a valid save: '+err.message);return;}try{gameState=migrateState(data);autosave();renderAll();}catch(err){alert('Couldn\u2019t load this save: '+err.message);console.error('loadFromFile render error:',err);}};r.readAsText(f);e.target.value='';}
